          "answer": "<code>contains</code> вернёт false, <code>find</code> — <code>m.end()</code>; размер останется 0. <code>m[\"x\"]</code> вставит запись со значением 0 и вернёт ссылку на это значение; размер станет 1. Все три варианта начинаются с отдельной пустой карты."
