          "html": "За восемь добавлений созданы 8 новых элементов, а старые переносились сериями 1, 2 и 4. Итого <code>8 + 1 + 2 + 4 = 15</code> действий. Девятое добавление требует нового роста: 8 переносов и одно создание, то есть сразу 9 действий. За девять добавлений сумма уже 24. Медленный отдельный шаг не отменяет дешёвой серии."
