          "html": "<code>queue</code> соблюдает FIFO (first in, first out: «первым пришёл — первым вышел», первым извлекается первым добавленный). <code>stack</code> — LIFO (last in, first out: первым извлекается последний добавленный). Их <code>pop()</code> удаляет элемент, а не возвращает его; перед удалением читают <code>front()</code> или <code>top()</code>, проверив непустоту."
