      "lead": "Для удаления нулей мало показать правильный результат на одном массиве. Нужно объяснить, какие элементы уже обработаны, где лежит готовая часть ответа и почему следующий шаг ничего нужного не уничтожит. Это рассуждение об инварианте прохода.",
