          "html": "У <code>{0, 3, 0, 4, 5}</code> сохранённая часть постепенно становится <code>{3}</code>, <code>{3, 4}</code>, <code>{3, 4, 5}</code>. Получается <code>O(n)</code> времени: каждый элемент рассматриваем один раз; два индекса требуют <code>O(1)</code> дополнительной памяти. Удалять каждый встретившийся ноль из середины вектора дороже: каждое удаление может сдвигать хвост, и суммарно на некоторых входах получится квадратичное число перемещений."
