          "html": "<strong>Обход дерева по уровням.</strong> Очередь хранит ещё не обработанные вершины. Чтобы выделить один уровень, запоминаем её размер <code>k</code> <em>до</em> обработки и извлекаем ровно <code>k</code> вершин. Их дети добавляются в конец и относятся уже к следующему уровню. Если вместо этого продолжать до опустошения растущей очереди, граница уровней исчезнет. Рассуждение без списка посещённых верно для настоящего дерева: нет циклов и одной общей дочерней вершины у разных родителей."
