          "answer": "<p>Предыдущее вхождение последней <code>a</code> уже вне окна: граница не должна отступать с <code>2</code> на <code>1</code>. Для Two Sum достаточно входа <code>[3]</code> с целью <code>6</code>: правильного ответа нет, потому что требуются две разные позиции. Вставка до поиска может нарушить это условие.</p>"
