          "type": "text",
          "html": "Ниже — самостоятельная программа с этим правилом. <code>std::size_t</code> — беззнаковый тип для размеров и индексов; здесь длина ни одного участка не превосходит размера входного вектора. Сравниваем соседние значения, а не вычитаем их, чтобы определение направления не требовало потенциально переполняющейся разности."
