          "answer": "<p>Максимальная длина равна <code>2</code>. После пары <code>2, 1</code> убывающая длина <code>2</code>. На <code>1, 3</code> возрастающая становится <code>2</code>, затем <code>3, 2</code> снова даёт убывающую <code>2</code>. Число поворота принадлежит обоим соседним участкам: например, <code>3</code> заканчивает <code>[1, 3]</code> и начинает <code>[3, 2]</code>. Два счётчика учитывают это без отката индекса.</p>"
