        {
          "type": "text",
          "html": "Назначим <code>A → бит 0</code>, <code>B → бит 1</code>, <code>C → бит 2</code>. Тогда множество <code>{A, C}</code> имеет маску <code>101₂</code>, то есть число <code>5</code>. Повторная буква <code>A</code> не добавляет нового бита. Такая <em>битовая маска</em> хранит факт присутствия, но не число повторений, порядок появления или форму дерева, в котором встретились буквы."
        },
        {
          "type": "text",
          "html": "<table><thead><tr><th>Операция</th><th>Смысл для масок</th></tr></thead><tbody><tr><td><code>a | b</code> — побитовое ИЛИ</td><td>Бит результата равен <code>1</code>, если включён хотя бы в одной маске: объединение множеств.</td></tr><tr><td><code>a &amp; b</code> — побитовое И</td><td>Бит равен <code>1</code>, только если включён в обеих масках: пересечение.</td></tr><tr><td><code>one &lt;&lt; bit</code> — сдвиг влево</td><td>Один установленный младший бит переносится в позицию <code>bit</code>, если сдвиг допустим для типа.</td></tr></tbody></table>"
        },
        {
          "type": "text",
          "html": "Знак <code>&amp;</code> в <code>a &amp; b</code> — бинарная операция над двумя числами; здесь он не означает взятие адреса или объявление ссылки. Запись <code>mask |= flag</code> сохраняет в <code>mask</code> объединение прежней маски с <code>flag</code>. Чтобы проверить флаг, вычисляют <code>(mask &amp; flag) != 0</code>."
        },
        {
          "type": "diagram",
          "title": "Проверяем число 13 = 1101₂",
          "mode": "flow",
          "items": [
            {
              "title": "bit=0, маска 0001",
              "html": "1101 & 0001 = 0001: единица есть, count=1."
            },
            {
              "title": "bit=1, маска 0010",
              "html": "1101 & 0010 = 0000: count остаётся 1."
            },
            {
              "title": "bit=2, маска 0100",
              "html": "1101 & 0100 = 0100: count=2."
            },
            {
              "title": "bit=3, маска 1000",
              "html": "1101 & 1000 = 1000: count=3."
            }
          ]
        },
        {
          "type": "text",
          "html": "У числа <code>13 = 1101₂</code> включены позиции <code>0</code>, <code>2</code> и <code>3</code>: единиц три. Для подсчёта можно проверить все позиции по очереди. Другой способ — на каждом шаге убирать одну младшую единицу, пока число не станет нулём. Следующий блок содержит заголовки и законченные функции, но не <code>main</code>; это не отдельная запускаемая программа."
        },
        {
          "type": "text",
          "html": "В функциях используется <code>std::uint64_t</code> — точный беззнаковый 64-битный тип, если платформа его предоставляет. <code>std::numeric_limits&lt;T&gt;::digits</code> сообщает число значащих двоичных разрядов целого типа <code>T</code>, без знакового бита. Для показанного <code>uint64_t</code> это <code>64</code>. Выражение <code>std::uint64_t{1}</code> создаёт единицу нужного типа <em>до</em> сдвига."
        },
        {
          "type": "code",
          "caption": "Две полные функции и стандартный popcount из C++20",
          "code": "#include <bit>\n#include <cstdint>\n#include <limits>\n\nint count_bits(std::uint64_t value) {\n    int count = 0;\n    for (int bit = 0; bit < std::numeric_limits<std::uint64_t>::digits; ++bit)\n        if ((value & (std::uint64_t{1} << bit)) != 0) ++count;\n    return count;\n}\n\nint count_by_clearing(std::uint64_t value) {\n    int count = 0;\n    while (value != 0) {\n        value &= value - 1;\n        ++count;\n    }\n    return count;\n}\nstatic_assert(std::popcount(std::uint64_t{13}) == 3);"
        },
        {
          "type": "text",
          "html": "В <code>count_bits</code> счётчик <code>bit</code> принимает значения от <code>0</code> до <code>63</code>. Выражение <code>std::uint64_t{1} &lt;&lt; bit</code> даёт флаг проверяемой позиции. Побитовое И оставляет либо этот флаг, либо ноль; при ненулевом результате увеличиваем число найденных единиц. Для нулевого входа все проверки ложны и функция возвращает <code>0</code>."
        },
        {
          "type": "text",
          "html": "<strong>Почему value &amp; (value - 1) убирает одну единицу.</strong> У ненулевого числа справа от младшей единицы стоят только нули. Вычитание единицы заменяет эту единицу нулём, а правые нули — единицами; более старшие биты не меняются. Побитовое И с исходным числом оставит старшие биты, уберёт выбранную единицу и не сохранит вновь появившиеся справа единицы."
        },
        {
          "type": "text",
          "html": "<table><thead><tr><th>До шага</th><th>После вычитания 1</th><th>Результат И</th></tr></thead><tbody><tr><td><code>1101₂</code> (<code>13</code>)</td><td><code>1100₂</code></td><td><code>1100₂</code> (<code>12</code>)</td></tr><tr><td><code>1100₂</code> (<code>12</code>)</td><td><code>1011₂</code></td><td><code>1000₂</code> (<code>8</code>)</td></tr><tr><td><code>1000₂</code> (<code>8</code>)</td><td><code>0111₂</code></td><td><code>0000₂</code> (<code>0</code>)</td></tr></tbody></table>"
        },
        {
          "type": "text",
          "html": "В <code>count_by_clearing</code> условие <code>value != 0</code> проверяется до вычитания. Каждый проход убирает ровно одну исходную единицу и увеличивает <code>count</code>. Поэтому на числе <code>13</code> будет три итерации, а на нуле — ни одной. Присваивание <code>value &amp;= value - 1</code> означает «вычислить И и записать результат обратно в value»."
        },
        {
          "type": "text",
          "html": "В <code>&lt;bit&gt;</code> уже есть <code>std::popcount</code> для подходящего беззнакового целого типа: он возвращает число единичных битов. Последняя строка блока, <code>static_assert</code>, проверяет при компиляции, что для <code>13</code> результат равен <code>3</code>. Она не печатает число. Использование <code>popcount</code> не является обещанием одной конкретной машинной инструкции."
        },
        {
          "type": "text",
          "html": "Если рассматриваем фиксированный 64-битный тип, обе функции имеют ограниченное число итераций, то есть <code>O(1)</code> относительно размера внешнего входа. Если отдельно считать ширину числа <code>w</code> параметром задачи, первый способ требует <code>O(w)</code> проверок, второй — <code>O(k)</code> для <code>k</code> установленных битов. Эти оценки отвечают разным вопросам; нельзя объявлять второй способ всегда быстрее в наносекундах без измерения."
        },
        {
          "type": "note",
          "kind": "warn",
          "html": "У сдвига проверяют ширину <em>левого операнда после целочисленных продвижений</em>, а не тип переменной, в которую позже попадёт результат. В <code>std::uint64_t mask = 1 &lt;&lt; bit;</code> литерал <code>1</code> имеет тип <code>int</code>: присваивание не исправляет уже выполненный сдвиг. Отрицательное число позиций или число позиций не меньше ширины продвинутого левого операнда даёт неопределённое поведение. В показанном цикле исходная единица имеет подходящий беззнаковый тип и границы проверены заранее. Не заменяй <code>digits</code> на <code>sizeof</code>: <code>sizeof</code> измеряется в байтах и может включать не только значащие биты."
        },
        {
          "type": "self-check",
          "prompt": "Проследи второй способ для <code>8</code> и для <code>0</code>. Можно ли по маске <code>101₂</code> понять, встретилась ли <code>A</code> один раз или десять?",
          "answer": "<p>Для <code>8 = 1000₂</code> один шаг даёт <code>1000₂ &amp; 0111₂ == 0</code>, значит, ответ <code>1</code>. Для нуля цикл не выполняется, ответ <code>0</code>. Маска <code>101₂</code> сообщает только наличие <code>A</code> и <code>C</code>; частоты она не хранит.</p>"
        },
        {
          "type": "note",
          "kind": "tip",
          "html": "<strong>Источники и границы.</strong> Открытый проект N4861, HTML-представление на стороннем хостинге: <a href=\"https://timsong-cpp.github.io/cppwp/n4861/expr.bit.and\" target=\"_blank\" rel=\"noreferrer\">побитовое И</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/expr.or\" target=\"_blank\" rel=\"noreferrer\">побитовое ИЛИ</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/expr.shift\" target=\"_blank\" rel=\"noreferrer\">сдвиги</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/expr.ass\" target=\"_blank\" rel=\"noreferrer\">составное присваивание</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/conv.prom\" target=\"_blank\" rel=\"noreferrer\">целочисленные продвижения</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/bit.count\" target=\"_blank\" rel=\"noreferrer\">popcount</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/numeric.limits.members\" target=\"_blank\" rel=\"noreferrer\">digits</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/expr.sizeof\" target=\"_blank\" rel=\"noreferrer\">sizeof</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/cstdint\" target=\"_blank\" rel=\"noreferrer\">точные целочисленные типы</a>. Правило удаления младшей единицы доказано двоичным разбором выше; источники задают поведение операций и библиотечных средств."
        }
