          "html": "<strong>Источники и границы.</strong> Открытый проект N4861, HTML-представление на стороннем хостинге: <a href=\"https://timsong-cpp.github.io/cppwp/n4861/unord.req\" target=\"_blank\" rel=\"noreferrer\">unordered_map: ключи, emplace и сложность</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/optional.observe\" target=\"_blank\" rel=\"noreferrer\">проверка наличия optional</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/dcl.struct.bind\" target=\"_blank\" rel=\"noreferrer\">структурированное связывание</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/string.view.find\" target=\"_blank\" rel=\"noreferrer\">find и npos</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/cstdint\" target=\"_blank\" rel=\"noreferrer\">uint32_t</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/expr.shift\" target=\"_blank\" rel=\"noreferrer\">границы сдвига</a>. Индуктивное доказательство маски дано выше. Библиотечные источники подтверждают операции реестра, представление необязательного ответа и поиск позиции буквы."
