          "html": "<strong>Источники и границы.</strong> Открытый проект N4861, HTML-представление на стороннем хостинге: <a href=\"https://timsong-cpp.github.io/cppwp/n4861/unord.req\" target=\"_blank\" rel=\"noreferrer\">unordered_map: поиск, вставка и сложность</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/unord.map.elem\" target=\"_blank\" rel=\"noreferrer\">at</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/unique.ptr.create\" target=\"_blank\" rel=\"noreferrer\">make_unique</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/unique.ptr.single.observers\" target=\"_blank\" rel=\"noreferrer\">get</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/unique.ptr.single.ctor\" target=\"_blank\" rel=\"noreferrer\">перемещение unique_ptr</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/unique.ptr.single.dtor\" target=\"_blank\" rel=\"noreferrer\">уничтожение unique_ptr</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/except.ctor\" target=\"_blank\" rel=\"noreferrer\">освобождение при исключении</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/vector.modifiers\" target=\"_blank\" rel=\"noreferrer\">рост vector</a>. Реестр до перехода по рёбрам и доказательство обхода — рассуждение для этой задачи. Библиотечные правила объясняют поиск адресов, владение и устойчивость адресов отдельно выделенных объектов."
