          "html": "Для <code>AAABBCCCCD</code> после чтения первой серии <code>read == 3</code>, а после записи <code>A3</code> получим <code>write == 2</code>. Затем: <code>read == 5, write == 4</code> после <code>B2</code>; <code>read == 9, write == 6</code> после <code>C4</code>; наконец, <code>read == 10, write == 7</code> после <code>D</code>. Размер исходной строки пока всё ещё <code>10</code>. Готовый ответ занимает только её первые семь позиций."
