          "answer": "Первый вариант корректен: обычный вызов <code>constexpr</code>-функции может читать значение во время выполнения. До увеличения <code>counter</code> равен <code>6</code>, так что <code>b</code> станет <code>12</code>. Второй вариант некорректен: инициализатор <code>constexpr</code>-объекта должен быть константным выражением, а чтение данного изменяемого <code>counter</code> не подходит."
