          "answer": "Обычный <code>if</code> не устраняет требование корректности обеих веток конкретной функции. При инстанцировании <code>read_value&lt;int&gt;</code> в первой ветке получилось бы недопустимое <code>*value</code>. У <code>if constexpr</code> эта зависимая ветка для данного типа отбрасывается и не инстанцируется."
