          "html": "<strong>Ориентиры по версиям, не список для заучивания.</strong> C++11 добавил средства перемещения, лямбды и стандартные потоки; C++17 — <code>optional</code>, <code>variant</code>, <code>string_view</code>, <code>if constexpr</code> и новые гарантии непосредственного создания результата для ряда prvalue-выражений. В C++20 появились concepts, ranges, корутины, <code>jthread</code>, <code>consteval</code> и <code>constinit</code>. <code>expected</code> и <code>move_only_function</code> относятся к C++23, а не к используемой здесь базе C++20. Эти названия — карта соседних возможностей: их наличие в редакции стандарта не подтверждает поддержку вашей версией компилятора и библиотеки. В самой подглаве достаточно уметь объяснить применяемый механизм на примере."
