          "html": "<strong>Источники и границы.</strong> N4861 — открытый проект C++20, а не опубликованный стандарт ISO. <a href=\"https://timsong-cpp.github.io/cppwp/n4861/optional.optional\" target=\"_blank\" rel=\"noopener noreferrer\">[optional.optional]</a> и <a href=\"https://timsong-cpp.github.io/cppwp/n4861/optional.observe\" target=\"_blank\" rel=\"noopener noreferrer\">[optional.observe]</a> задают хранение значения, проверку наличия, разыменование, value и value_or; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/expr.call\" target=\"_blank\" rel=\"noopener noreferrer\">[expr.call]</a> и <a href=\"https://timsong-cpp.github.io/cppwp/n4861/expr.cond\" target=\"_blank\" rel=\"noopener noreferrer\">[expr.cond]</a> — вычисление аргументов и одной ветви условного оператора; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/dcl.struct.bind\" target=\"_blank\" rel=\"noopener noreferrer\">[dcl.struct.bind]</a> — собственный объект и привязки к его компонентам."
