          "code": "#include <iostream>\n#include <string>\n#include <string_view>\nint main() {\n    std::string owner = \"cat\";\n    std::string copy = owner;\n    std::string_view view = owner;\n    owner[0] = 'b';\n    std::cout << copy << ' ' << view; // cat bat\n}"
