          "html": "Недостаточно проверить лишь наличие владельца. Живой <code>vector</code> может перераспределить буфер, а <code>erase</code> — инвалидировать доступ к затронутым элементам без смены общей ёмкости. Перед использованием старого представления нужны и живые элементы, и допустимость сохранённых адресов по правилам конкретной операции. Ненулевой адрес и const-тип этого не доказывают. Отдельно помни о длине <code>string_view</code>: даже действительный адрес не превращает подстроку в C-строку с нулём на её границе."
