          "html": "Есть ещё один вопрос: хранит диапазон готовые результаты или вычисляет их при обращении? <strong>Ленивый</strong> доступ откладывает действия до обхода. Например, <code>views::transform</code> применяет функцию к читаемому элементу; само построение представления не создаёт vector преобразованных чисел."
