          "html": "<strong>Источники и границы.</strong> N4861 — открытый проект C++20, а не опубликованный стандарт ISO. <a href=\"https://timsong-cpp.github.io/cppwp/n4861/basic.life\" target=\"_blank\" rel=\"noopener noreferrer\">[basic.life]</a> разделяет предоставленную память и время жизни объекта; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/dcl.align\" target=\"_blank\" rel=\"noopener noreferrer\">[dcl.align]</a> задаёт alignas, <a href=\"https://timsong-cpp.github.io/cppwp/n4861/new.delete.placement\" target=\"_blank\" rel=\"noopener noreferrer\">[new.delete.placement]</a> — стандартную невыделяющую форму; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/specialized.destroy\" target=\"_blank\" rel=\"noopener noreferrer\">[specialized.destroy]</a> — destroy_at; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/except.ctor\" target=\"_blank\" rel=\"noopener noreferrer\">[except.ctor]</a> — очистку завершённых подобъектов при отказе конструктора. Учёт слотов и его инвариант — условия нашего пула, а не готовый универсальный аллокатор."
