          "html": "<strong>Условие.</strong> Дан <code>vector&lt;int&gt;</code>. Нужно вернуть не более k пар «код, число появлений»: раньше идут более частые коды, а при одинаковой частоте — меньший код. Для <code>503,404,503,500,404,503,401</code> и <code>k=3</code> ответ должен быть <code>(503,3), (404,2), (401,1)</code>. Код 500 тоже встретился один раз, но уступает 401 по второму правилу. Это целые учебные метки, а не проверка допустимых HTTP-статусов. Пустой вход и k=0 дают пустой результат, исходный vector не меняем."
