          "type": "text",
          "html": "Предыдущая задача задала порядок при одинаковой частоте. Теперь прочитаем более короткий вариант для шести слов: <code>apple, banana, apple, cherry, banana, apple</code>. Нужно посчитать их частоты и вывести по убыванию. В этом наборе частоты различны, поэтому дополнительное правило равенства на вывод не повлияет. Оно понадобится, как только изменится вход."
