          "type": "text",
          "html": "Конструктор <code>sorted(freq.begin(), freq.end())</code> читает диапазон записей map и создаёт в vector собственные пары со строками и числами. Карта хранит ключ как <code>const string</code>, но в новых парах ключ уже обычное строковое значение: переставлять пары можно. Здесь есть цена копирования строк, а не только копирования коротких адресов. После создания вектора дальнейшая сортировка не меняет freq."
